### Pattern 1: Parallel HTTP Requests

```python
from concurrent.futures import ThreadPoolExecutor, as_completed
import urllib.request
import time

def fetch_url(url):
    """Fetch URL content"""
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            return url, response.status, len(response.read())
    except Exception as e:
        return url, None, str(e)

def parallel_fetch(urls, max_workers=10):
    """Fetch multiple URLs in parallel"""
    results = {}

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_url = {executor.submit(fetch_url, url): url for url in urls}

        for future in as_completed(future_to_url):
            url = future_to_url[future]
            try:
                url, status, size = future.result()
                results[url] = {'status': status, 'size': size}
                print(f"✓ {url}: {status}, {size} bytes")
            except Exception as e:
                results[url] = {'error': str(e)}
                print(f"✗ {url}: {e}")

    return results

if __name__ == "__main__":
    urls = [
        "http://example.com",
        "http://httpbin.org/get",
        "http://httpbin.org/delay/1",
    ]

    start = time.time()
    results = parallel_fetch(urls)
    print(f"\nFetched {len(results)} URLs in {time.time() - start:.2f}s")
```

### Pattern 2: Parallel File Processing

```python
from concurrent.futures import ProcessPoolExecutor
import os
import hashlib

def process_file(filepath):
    """Calculate hash of a file"""
    hasher = hashlib.md5()

    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            hasher.update(chunk)

    return filepath, hasher.hexdigest()

def parallel_hash_files(directory, extension=".txt"):
    """Hash all files with given extension in parallel"""
    files = [
        os.path.join(directory, f)
        for f in os.listdir(directory)
        if f.endswith(extension)
    ]

    results = {}
    with ProcessPoolExecutor() as executor:
        for filepath, filehash in executor.map(process_file, files):
            results[os.path.basename(filepath)] = filehash

    return results
```

### Pattern 3: Chunked Processing

```python
from concurrent.futures import ProcessPoolExecutor
import math

def process_chunk(chunk):
    """Process a chunk of data"""
    return sum(math.sqrt(x) for x in chunk)

def chunk_data(data, chunk_size):
    """Split data into chunks"""
    for i in range(0, len(data), chunk_size):
        yield data[i:i + chunk_size]

def parallel_process(data, chunk_size=10000, max_workers=4):
    """Process data in parallel chunks"""
    chunks = list(chunk_data(data, chunk_size))

    with ProcessPoolExecutor(max_workers=max_workers) as executor:
        results = list(executor.map(process_chunk, chunks))

    return sum(results)

if __name__ == "__main__":
    import time

    data = list(range(1_000_000))

    # Sequential
    start = time.time()
    sequential = sum(math.sqrt(x) for x in data)
    seq_time = time.time() - start

    # Parallel
    start = time.time()
    parallel = parallel_process(data)
    par_time = time.time() - start

    print(f"Sequential: {seq_time:.3f}s")
    print(f"Parallel: {par_time:.3f}s")
    print(f"Speedup: {seq_time/par_time:.2f}x")
```
